public class Main {
    static int countChar(String text, char target) {
        int count = 0;
        for (int i = 0; i < text.length(); i++) {
            if (text.charAt(i) == target) {
                count = count + 1;
            }
        }
        return count;
    }
    public static void main(String[] args) {
        System.out.println(countChar("banana", 'a'));
    }
}

